#[cfg(test)]
mod tests {
    /// Strictly ascending: binary search demands it, and it doubles as
    /// a dedup check.
    #[test]
    fn table_is_sorted_by_spell_id() {
        assert!(super::TABLE.windows(2).all(|w| w[0] < w[1]));
    }

    /// The fixtures' shields resolve, and a stranger does not.
    #[test]
    fn fixture_shields_resolve() {
        assert!(super::is_absorb_spell(17));
        assert!(super::is_absorb_spell(11426));
        assert!(super::is_absorb_spell(77535));
        assert!(!super::is_absorb_spell(0));
    }
}
